const HEADER = `// Generated by scripts/genDevices.ts from the Error.code enum of tests/skill/devices.openapi.json.
// Do not edit by hand: run \`bun run gen:devices <openapi.json>\` after the API adds a code.
`

export const renderCodes = (codes: readonly string[]): string =>
  `${HEADER}
export const API_ERROR_CODES = [
${codes.map((code) => `  '${code}',`).join('\n')}
] as const

export type ApiErrorCode = (typeof API_ERROR_CODES)[number]
`

export const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

/** Reads the Error.code enum out of an OpenAPI 3.x document held in memory. */
export const extractCodes = (document: unknown): string[] => {
  const components = isRecord(document) ? document.components : undefined
  const schemas = isRecord(components) ? components.schemas : undefined
  const errorSchema = isRecord(schemas) ? schemas.Error : undefined
  const properties = isRecord(errorSchema) ? errorSchema.properties : undefined
  const errorObject = isRecord(properties) ? properties.error : undefined
  const inner =
    isRecord(errorObject) && isRecord(errorObject.properties) ? errorObject : errorSchema
  const innerProperties = isRecord(inner) ? inner.properties : undefined
  const code = isRecord(innerProperties) ? innerProperties.code : undefined
  const values = isRecord(code) ? code.enum : undefined
  if (!Array.isArray(values) || !values.every((value) => typeof value === 'string')) {
    throw new Error('The document has no Error.code enum')
  }
  return values
}
